import pytest
import rank


def test_iteration_no_parameter_accepted():
    """Test that iteration_no parameter is accepted and bonus fields are present"""
    r = rank.Rank({})
    result = r.score({}, {}, {}, None, None, None, iteration_no=5)
    assert 'iteration_bonus' in result
    assert 'base_score' in result
    assert isinstance(result['iteration_bonus'], (int, float))


def test_score_audit_nested_structure():
    """Test that _score_audit handles nested test_plan_audit_result structure"""
    r = rank.Rank({})
    nested = {
        'test_plan_audit_result': {
            'overall_assessment': {
                'recommendation': 'reject'
            }
        }
    }
    score = r._score_audit(None, nested)
    assert score < 1.0


def test_message_includes_bonus_info():
    """Test that message includes base score and bonus information"""
    r = rank.Rank({})
    result = r.score({}, {}, {}, None, None, None, iteration_no=2)
    assert 'base' in result['message']
    assert 'bonus' in result['message']


def test_basic_scoring_works():
    """Test that basic scoring still works for simple inputs"""
    r = rank.Rank({})
    run_result = {'results': {'case1': {'success': True}, 'case2': {'success': False}}}
    result = r.score(run_result, {}, {}, None, None, None)
    assert 0.0 <= result['overall_score'] <= 1.0
    assert 'scores' in result
    assert 'rank' in result
    assert 'compile_score' in result['scores']
